import{_ as t,o as a,c as s,a3 as o}from"./chunks/framework.Ki30n65y.js";const u=JSON.parse('{"title":"Requirements","description":"","frontmatter":{},"headers":[],"relativePath":"install/requirements.md","filePath":"install/requirements.md"}'),r={name:"install/requirements.md"};function i(n,e,d,c,l,h){return a(),s("div",null,[...e[0]||(e[0]=[o(`<h1 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;Requirements&quot;">​</a></h1><p>This page lists what you need before you install DepGate in production. For a trial on one machine, see the <a href="/depgate/guide/quick-start">Quick start</a>.</p><h2 id="architecture-at-a-glance" tabindex="-1">Architecture at a glance <a class="header-anchor" href="#architecture-at-a-glance" aria-label="Permalink to &quot;Architecture at a glance&quot;">​</a></h2><p>A DepGate installation has three parts:</p><table tabindex="0"><thead><tr><th>Component</th><th>Role</th><th>Notes</th></tr></thead><tbody><tr><td><strong>DepGate</strong></td><td>Web interface, REST API and every package registry, in one container image.</td><td>Stateless. Run one or more replicas.</td></tr><tr><td><strong>PostgreSQL 15 or later</strong> (17 recommended)</td><td>Configuration, policies, audit data.</td><td>Your own server, a managed service, or the bundled stack.</td></tr><tr><td><strong>Redis 7</strong></td><td>Metadata cache and background job queues.</td><td>One endpoint, <code>maxmemory-policy noeviction</code>.</td></tr></tbody></table><p>Package files from public registries are kept in each DepGate instance&#39;s own <a href="/depgate/admin/artifact-cache">artifact cache</a> on local disk; everything else is streamed from the upstream registry.</p><h2 id="host" tabindex="-1">Host <a class="header-anchor" href="#host" aria-label="Permalink to &quot;Host&quot;">​</a></h2><ul><li>A Linux host (or any machine that runs Docker) with <strong>Docker Engine</strong> and <strong>Docker Compose v2</strong>, or a Kubernetes cluster (1.30 or later) for <a href="./kubernetes">Install on Kubernetes</a>.</li><li>At least <strong>2 vCPU and 4 GB RAM</strong> for a team; see <a href="#sizing">Sizing</a> for larger installations.</li><li>Ports <strong>443</strong> and <strong>80</strong> free. With your own TLS proxy in front, only port 80 is used.</li></ul><h2 id="network" tabindex="-1">Network <a class="header-anchor" href="#network" aria-label="Permalink to &quot;Network&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Direction</th><th>Destination</th><th>Why</th></tr></thead><tbody><tr><td>Inbound</td><td>HTTPS (443) from developer machines and CI runners</td><td>Package downloads, web interface, API.</td></tr><tr><td>Outbound</td><td>The public registries you proxy: registry.npmjs.org, pypi.org and files.pythonhosted.org, repo1.maven.org, proxy.golang.org, api.nuget.org, crates.io (with index.crates.io and static.crates.io), repo.packagist.org, rubygems.org</td><td>Fetching packages.</td></tr><tr><td>Outbound</td><td><code>api.osv.dev</code></td><td>Known vulnerabilities.</td></tr><tr><td>Outbound</td><td><code>api.deps.dev</code>, <code>api.securityscorecards.dev</code></td><td>Missing licenses and publish dates; project health scores.</td></tr><tr><td>Outbound</td><td><code>github.com</code> (malicious-packages feed), <code>epss.empiricalsecurity.com</code></td><td>Malware feed and daily EPSS scores.</td></tr><tr><td>Outbound</td><td>Your internal registries, SMTP server and webhook endpoints</td><td>Optional.</td></tr></tbody></table><p>A corporate outbound proxy is supported. See <a href="./https-and-networking#corporate-outbound-proxy">HTTPS and networking</a>.</p><h2 id="host-name-and-certificate" tabindex="-1">Host name and certificate <a class="header-anchor" href="#host-name-and-certificate" aria-label="Permalink to &quot;Host name and certificate&quot;">​</a></h2><p>Choose the address people will use, for example <code>https://depgate.example.com</code>, and either:</p><ul><li>a <strong>TLS certificate</strong> for that name (from your company CA or a public CA), which DepGate serves itself; or</li><li><strong>your own TLS proxy or load balancer</strong> in front of DepGate, which terminates TLS.</li></ul><h2 id="database" tabindex="-1">Database <a class="header-anchor" href="#database" aria-label="Permalink to &quot;Database&quot;">​</a></h2><p><strong>PostgreSQL 15 or later</strong> (17 recommended). Create an empty database and a user that owns it, once, before DepGate first starts. DepGate creates its tables on first start and upgrades them on later starts (see <a href="./operations#upgrade">Operate and upgrade</a>), but it does not create the database or the user. As a PostgreSQL superuser:</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">CREATE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> ROLE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> depgate </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">LOGIN</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> PASSWORD</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;…&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;      </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- DB_USER and DB_PASSWORD</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">CREATE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> DATABASE</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> depgate</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> OWNER</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> depgate;        </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- DB_NAME</span></span></code></pre></div><p>On a managed service (Amazon RDS, Cloud SQL, Azure Database for PostgreSQL), create them in the service&#39;s console or with the same statements. Use a new database: one that already has tables, such as a development database, stops DepGate at startup with <code>relation &quot;…&quot; already exists</code>, and nothing is changed. The all-in-one Docker setup creates its own database and needs none of this.</p><p>Each DepGate instance opens up to <code>DB_POOL_SIZE</code> (20) connections, plus two more while it starts: allow 25 per instance in <code>max_connections</code>, so two replicas need about 45 plus the server&#39;s own headroom.</p><p><strong>Redis 7</strong> (or compatible), configured with:</p><ul><li><code>maxmemory-policy noeviction</code>: job queues live in Redis and must never be evicted.</li><li>AOF persistence (<code>appendonly yes</code>, <code>appendfsync everysec</code>).</li><li>A password, and one endpoint: a standalone server, or a primary with a replica behind one failover address (for example Memorystore Standard). Redis Cluster mode is not supported.</li></ul><p>Managed Redis services (ElastiCache, Azure Cache for Redis, Memorystore) often default to an evicting policy. Change it, or give the job queues their own Redis with <code>QUEUE_REDIS_URL</code>. These services also block the <code>CONFIG</code> command, so DepGate cannot read the policy and <code>/readyz</code> reports it as <code>unknown</code>; verify it in the service&#39;s console.</p><p>If you do not have database servers yet, the all-in-one setup runs PostgreSQL and Redis on the same host as DepGate, set up this way. See <a href="./docker#all-in-one">Install with Docker</a>.</p><h2 id="sizing" tabindex="-1">Sizing <a class="header-anchor" href="#sizing" aria-label="Permalink to &quot;Sizing&quot;">​</a></h2><p>Memory use is driven by how many distinct packages your organization requests per hour.</p><table tabindex="0"><thead><tr><th>Deployment</th><th>Distinct packages per hour</th><th>Redis <code>maxmemory</code></th><th>DepGate container RAM</th></tr></thead><tbody><tr><td>Evaluation</td><td>fewer than 500</td><td>512 MB</td><td>1 GB</td></tr><tr><td>Team (up to 50 developers, some CI)</td><td>about 3,000</td><td>2 GB</td><td>3–4 GB</td></tr><tr><td>Organization (hundreds of developers)</td><td>about 15,000</td><td>8 GB</td><td>12–16 GB</td></tr><tr><td>Large (thousands of pipelines)</td><td>50,000 or more</td><td>24 GB or more</td><td>Use a separate queue Redis</td></tr></tbody></table><p>Leave about 40 % of the Redis host&#39;s memory above <code>maxmemory</code> for persistence rewrites.</p><h2 id="package-clients" tabindex="-1">Package clients <a class="header-anchor" href="#package-clients" aria-label="Permalink to &quot;Package clients&quot;">​</a></h2><p>DepGate works with the standard clients of each ecosystem: npm, Yarn and pnpm; pip, Poetry and uv; Maven and Gradle; the <code>go</code> command; <code>dotnet</code> and NuGet; Cargo; Composer; and RubyGems/Bundler.</p><div class="warning custom-block"><p class="custom-block-title">Go needs HTTPS</p><p>The <code>go</code> command sends credentials only over HTTPS. Go clients therefore need DepGate behind TLS.</p></div>`,30)])])}const g=t(r,[["render",i]]);export{u as __pageData,g as default};
